import argparse,contextlib,io
for typ,default in [(float,0.0),(int,0)]:
 p=argparse.ArgumentParser(); p.add_argument('--top_k',type=typ,default=default)
 for args in [[],['--top_k','5'],['--top_k','5.0']]:
  try:
   with contextlib.redirect_stderr(io.StringIO()): v=p.parse_args(args).top_k
   print(typ.__name__,args,repr(v),type(v).__name__)
  except SystemExit: print(typ.__name__,args,'rejected')
